<?php
require_once '../includes/auth.php'; require_role('admin'); require_once '../config/db.php';
$page_title='Teacher Management';$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(isset($_POST['add_teacher'])){$username=trim($_POST['username']??'');$name=trim($_POST['name']??'');$password=$_POST['password']??'';if(!$username||!$name||strlen($password)<6)$err='Enter teacher name, email and a password of at least 6 characters.';else{$st=$conn->prepare("SELECT username FROM tbl_trs WHERE username=?");$st->bind_param('s',$username);$st->execute();if($st->get_result()->num_rows)$err='A teacher with that email already exists.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$st=$conn->prepare("INSERT INTO tbl_trs(username,name,subject,password,notes_file_path,semester,approved) VALUES(?,?, '',?,'',NULL,1)");$st->bind_param('sss',$username,$name,$hash);if($st->execute())$msg='Teacher added. Assign their subjects and semesters from Timetable → Teaching Assignments.';else$err='Could not add teacher.';}}}
    if(isset($_POST['edit_teacher'])){$username=trim($_POST['username']??'');$name=trim($_POST['name']??'');$st=$conn->prepare("UPDATE tbl_trs SET name=? WHERE username=?");$st->bind_param('ss',$name,$username);if($st->execute())$msg='Teacher name updated.';else$err='Could not update teacher.';}
    if(isset($_POST['toggle_teacher'])){$username=trim($_POST['username']??'');$st=$conn->prepare("UPDATE tbl_trs SET approved=IF(approved=1,0,1) WHERE username=?");$st->bind_param('s',$username);$st->execute();$msg='Teacher status changed.';}
    if(isset($_POST['remove_teacher'])){$username=trim($_POST['username']??'');$counts=[];foreach(['tbl_timetable','tbl_hourly_attendance','tbl_assignments','tbl_notes','tbl_student_assignments','tbl_teacher_teaching'] as $table){$column=($table==='tbl_hourly_attendance')?'marked_by':'teacher_username';$st=$conn->prepare("SELECT COUNT(*) c FROM {$table} WHERE {$column}=?");$st->bind_param('s',$username);$st->execute();$counts[$table]=(int)$st->get_result()->fetch_assoc()['c'];}if(array_sum($counts)>0)$err='This teacher has academic records or teaching assignments. Deactivate the teacher instead of permanently deleting them.';else{$st=$conn->prepare("DELETE FROM tbl_trs WHERE username=?");$st->bind_param('s',$username);if($st->execute())$msg='Teacher removed permanently.';else$err='Could not remove teacher.';}}
}
$rows=$conn->query("SELECT username,name,approved FROM tbl_trs ORDER BY approved DESC,name ASC");
require '../includes/header.php';
?>
