<div class="row g-4"><div class="col-xl-4"><div class="glass-card"><div class="section-kicker">NEW TEACHER</div><h5>Add Teacher</h5><p class="small-muted">Do not assign a subject or semester here. Those are teaching assignments and can differ by semester.</p><form method="POST"><input type="hidden" name="add_teacher" value="1"><label class="form-label">Teacher name</label><input class="form-control mb-3" name="name" required><label class="form-label">Email / Username</label><input class="form-control mb-3" type="email" name="username" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="6" required><button class="btn btn-primary w-100">Add Teacher</button></form></div></div>
<div class="col-xl-8"><div class="glass-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><div class="section-kicker">FACULTY DIRECTORY</div><h5>Teachers</h5></div><a class="btn btn-sm btn-primary" href="timetable.php">Assign Subjects / Timetable</a></div><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>Teacher</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php if($rows->num_rows===0):?><tr><td colspan="3" class="empty">No teachers found.</td></tr><?php endif;?><?php while($t=$rows->fetch_assoc()):?><tr><td><strong><?php echo e($t['name']);?></strong><br><span class="small-muted"><?php echo e($t['username']);?></span></td><td><?php echo $t['approved']?'<span class="badge text-bg-success">Active</span>':'<span class="badge text-bg-secondary">Inactive</span>';?></td><td class="text-end"><div class="d-flex justify-content-end gap-2 flex-wrap"><button type="button" class="btn btn-sm btn-light edit-teacher-btn" data-bs-toggle="modal" data-bs-target="#editTeacherModal" data-username="<?php echo e($t['username']);?>" data-name="<?php echo e($t['name']);?>">Edit</button><form method="POST"><input type="hidden" name="toggle_teacher" value="1"><input type="hidden" name="username" value="<?php echo e($t['username']);?>"><button class="btn btn-sm <?php echo $t['approved']?'btn-warning':'btn-success';?>"><?php echo $t['approved']?'Deactivate':'Activate';?></button></form><form method="POST" onsubmit="return confirm('Permanently remove this teacher? This is allowed only when there are no academic records or teaching assignments.');"><input type="hidden" name="remove_teacher" value="1"><input type="hidden" name="username" value="<?php echo e($t['username']);?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></div></td></tr><?php endwhile;?></tbody></table></div></div></div></div>
<div class="modal fade" id="editTeacherModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content glass-modal"><form method="POST"><div class="modal-header"><h5 class="modal-title">Edit Teacher</h5><button class="btn-close btn-close-white" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="edit_teacher" value="1"><input type="hidden" name="username" id="editTeacherUsername"><label class="form-label">Teacher name</label><input class="form-control" name="name" id="editTeacherName" required><p class="small-muted mt-3 mb-0">Subjects and semesters are managed separately under Teaching Assignments.</p></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Save Changes</button></div></form></div></div></div>
